	private static class ReflectiveAccess {
		private static Method UPPER_BOUND;
		private static Throwable initError;

		static {
			Method upperBound = null;
			try {
				upperBound = Permit.getMethod(Types.class, "upperBound", Type.class);
			} catch (Throwable e) {
				initError = e;
